import{_ as e,c as o,o as r,a3 as i}from"./chunks/framework.Dk6sf0Ip.js";const p=JSON.parse('{"title":"Paso a Paso: Creación de un Nuevo Artículo (Cubierta)","description":"","frontmatter":{},"headers":[],"relativePath":"CasosParticulares/cubiertas/crearcuiertas.md","filePath":"CasosParticulares/cubiertas/crearcuiertas.md","lastUpdated":1759323946000}'),t={name:"CasosParticulares/cubiertas/crearcuiertas.md"};function c(n,a,s,l,d,u){return r(),o("div",null,a[0]||(a[0]=[i('<h1 id="paso-a-paso-creacion-de-un-nuevo-articulo-cubierta" tabindex="-1">Paso a Paso: Creación de un Nuevo Artículo (Cubierta) <a class="header-anchor" href="#paso-a-paso-creacion-de-un-nuevo-articulo-cubierta" aria-label="Permalink to &quot;Paso a Paso: Creación de un Nuevo Artículo (Cubierta)&quot;">​</a></h1><p>Este formulario es crucial para dar de alta el artículo en el sistema antes de poder ingresarlo al stock.</p><h2 id="_1-datos-basicos-e-identificacion-imagen-2-agregar-articulo-servicio" tabindex="-1">1. Datos Básicos e Identificación (Imagen 2: Agregar Artículo/Servicio) <a class="header-anchor" href="#_1-datos-basicos-e-identificacion-imagen-2-agregar-articulo-servicio" aria-label="Permalink to &quot;1. Datos Básicos e Identificación (Imagen 2: Agregar Artículo/Servicio)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Nombre</th><th>Que se ingresa</th><th>Ejemplo</th></tr></thead><tbody><tr><td><code>Nombre</code></td><td>Ingresa la <strong>Marca y el Código</strong> de la cubierta</td><td>Ejemplo: Pirelli P7 21008.</td></tr><tr><td><code>Descripción</code></td><td>Ingresa el <strong>Modelo + Fecha + Tipo + Medida</strong></td><td><em>Ejemplo: TR88 - 47/21- LISA - 295</em></td></tr><tr><td><code>Características</code></td><td>Campo para información adicional no estructurada.</td><td>(Opcional, si no es obligatorio).</td></tr><tr><td><code>Categoría</code></td><td>Selecciona la categoría <strong>&quot;ARTÍCULOS -&gt; CUBIERTAS&quot;</strong> del menú desplegable.</td><td></td></tr><tr><td><code>Cod. interno</code></td><td>Ingresa el <strong>código único</strong> de la cubierta (código de fábrica o interno de tu negocio)</td><td></td></tr><tr><td><code>Filtros</code></td><td>Selecciona el filtro <strong>&quot;1.8 Cubiertas&quot;</strong> del menú desplegable.</td><td></td></tr></tbody></table><h2 id="_2-configuracion-de-ubicacion-y-precios" tabindex="-1">2. Configuración de Ubicación y Precios <a class="header-anchor" href="#_2-configuracion-de-ubicacion-y-precios" aria-label="Permalink to &quot;2. Configuración de Ubicación y Precios&quot;">​</a></h2><p>El resto de la configuración se encuentra debajo de la sección de datos básicos, desplegando los menús de programación y marcando casillas.</p><h3 id="_1-ubicacion-1-programacion-de-la-ubicacion" tabindex="-1">1. <strong>Ubicación (1.-PROGRAMACIÓN DE LA UBICACIÓN):</strong> <a class="header-anchor" href="#_1-ubicacion-1-programacion-de-la-ubicacion" aria-label="Permalink to &quot;1. **Ubicación (1.-PROGRAMACIÓN DE LA UBICACIÓN):**&quot;">​</a></h3><ul><li><p>Debes hacer clic en la casilla <strong>□ Ubicación</strong>.</p></li><li><p>Al activarla, se abrirá la sección donde debes <strong>seleccionar el depósito</strong> al cual va a ingresar por defecto.</p></li><li><p><strong>Selecciona el depósito &quot;CUBIERTAS&quot;.</strong></p></li></ul><h3 id="_2-precios-6-programacion-del-precio" tabindex="-1">2. <strong>Precios (6.-PROGRAMACIÓN DEL PRECIO):</strong> <a class="header-anchor" href="#_2-precios-6-programacion-del-precio" aria-label="Permalink to &quot;2. **Precios (6.-PROGRAMACIÓN DEL PRECIO):**&quot;">​</a></h3><ul><li><p>Desplázate hacia abajo hasta que veas la sección.</p></li><li><p>Debes hacer clic en la casilla <strong>□ Precios</strong>.</p></li><li><p>Esto te permitirá colocar el <strong>valor de compra</strong> del artículo que estás creando. ○ <em>(Nota: La imagen muestra varias opciones de programación. **Solo activa &quot;Precios&quot; **y **&quot;Ubicación&quot; **por ahora, siguiendo el flujo de ingreso).</em></p></li></ul><h3 id="_3-finalizar-la-creacion" tabindex="-1"><strong>3. Finalizar la Creación</strong> <a class="header-anchor" href="#_3-finalizar-la-creacion" aria-label="Permalink to &quot;**3. Finalizar la Creación**&quot;">​</a></h3><ul><li><p>Una vez completados todos los campos obligatorios (⋆) y configurados la <strong>Ubicación</strong> y los <strong>Precios</strong>:</p></li><li><p>Haz clic en el botón azul <strong>GUARDAR</strong> en la esquina superior derecha.</p></li></ul><p>Al hacer esto, el nuevo artículo (&quot;Cubierta&quot;) quedará registrado en el sistema y automáticamente seleccionado en la ventana &quot;Agregar actividad&quot; del remito de ingreso, permitiendo continuar con el flujo original.</p>',13)]))}const b=e(t,[["render",c]]);export{p as __pageData,b as default};
